using System;
using System.Collections.Generic;
using System.Linq;

namespace FrioCalc.Psychrometrics.Processes;

// [4.17] Curso ORIGINAL guiado por el orden del cap. 1 ASHRAE 2025.
// No reproduce textualmente el Handbook ni los ejercicios de una presentación.
public sealed record AshraeStudyUnit(
    string Id,string AshraeSection,string Title,string Definition,
    string Derivation,string Origin,string Interpretation,
    string Limitation,string EquationKey,string Example,string Source)
{
    public string DisplayTitle => AshraeSection+". "+Title;
}

public sealed record AshraeEquation(
    string Key,string Title,string Left,string Numerator,string Denominator,
    string Units,string Derivation,string Origin,string Limitations);

public sealed record ChartConstructionStep(
    int Number,string Title,string WhatToDo,string WhyThisMatters,
    string NumericalExample,string Basis,string UnitId)
{
    public string DisplayTitle => Number.ToString("00")+". "+Title;
}

public static class AshraeStudyCatalog
{
    public const string Book="ASHRAE Handbook—Fundamentals (2025)";
    public const string PrimarySource="ASHRAE Handbook—Fundamentals 2025, cap. 1 Psychrometrics, https://handbook.ashrae.org/Handbooks/F25/SI/F25_Ch01/F25_Ch01_si.aspx";
    public const string SecondarySource="PsychroLib, funciones de aire húmedo: https://psychrometrics.github.io/psychrolib/api_docs.html";
    public static IReadOnlyList<AshraeStudyUnit> Units { get; }=new[]
    {
        new AshraeStudyUnit("A1", "1", "Composición del aire húmedo", "Mezcla de aire seco y vapor de agua. El aire seco contiene principalmente nitrógeno y oxígeno; el vapor es el componente cuya masa cambia en los procesos de humidificación y condensación.", "La ley de Dalton establece que la presión absoluta total P es la suma de las presiones parciales del aire seco y del vapor. Cada componente ocupa el volumen de la mezcla a la misma temperatura.", "La masa de aire seco se emplea como referencia invariante en los balances de climatización.", "Diferencie masa de aire seco, masa de vapor y masa total; el contenido de agua se expresa por kilogramo de aire seco.", "", "Dalton|W", "A presión de 101,325 kPa y presión de vapor de 1,585 kPa, la presión parcial del aire seco es 99,740 kPa.", Book),
        new AshraeStudyUnit("A2", "2", "Presión atmosférica y altitud", "La presión absoluta es la fuerza normal por unidad de área referida al vacío. La presión atmosférica disminuye al elevarse por la reducción del peso de la columna de aire.", "La ecuación hidrostática relaciona el gradiente vertical de presión con la densidad y la gravedad; la atmósfera estándar combina esta ecuación con un perfil térmico.", "P se expresa en kPa absolutos; la altitud en metros. La presión local se mide con un barómetro.", "A igual temperatura y humedad relativa, una menor presión aumenta la razón de humedad y el volumen específico.", "", "Dalton|v", "A nivel del mar, la atmósfera estándar asigna 101,325 kPa; a 3000 m, aproximadamente 70,1 kPa.", Book),
        new AshraeStudyUnit("A19", "3", "Temperatura de bulbo seco", "Temperatura del aire medida por un termómetro protegido de radiación y sin evaporación de agua. Describe el estado térmico sensible.", "La escala absoluta Kelvin se obtiene sumando 273,15 a la temperatura Celsius. La ley de gas ideal utiliza temperatura absoluta.", "t se expresa en °C; T en K. Una diferencia de 1 K equivale a una diferencia de 1 °C.", "En la carta el eje horizontal es la temperatura de bulbo seco; una línea vertical conserva t.", "", "TK", "25 °C corresponden a 298,15 K.", Book),
        new AshraeStudyUnit("A4", "4", "Presión de saturación y equilibrio de fases", "La presión de saturación es la presión parcial del vapor en equilibrio con agua líquida o hielo a determinada temperatura. Aumenta rápidamente con la temperatura.", "En equilibrio, ambas fases tienen igual potencial químico. La presión de saturación se evalúa mediante correlaciones de equilibrio de agua o hielo.", "p representa presión, en kPa; la presión de saturación depende de la temperatura, no de la cantidad de aire seco.", "La curva de saturación fija el máximo contenido de vapor en la fase gaseosa a una presión y temperatura dadas.", "", "Ws|PwsIce|PwsWater|PwsExp", "A 25 °C, la presión de saturación del agua es aproximadamente 3,17 kPa.", Book),
        new AshraeStudyUnit("A5", "5", "Razón de humedad, humedad específica y humedad volumétrica", "La razón de humedad W es la masa de vapor por kilogramo de aire seco. La humedad específica es la masa de vapor por kilogramo de mezcla. La humedad volumétrica es la masa de vapor por unidad de volumen.", "Aplicando Dalton y las leyes de gas ideal a cada componente se obtiene W a partir de sus presiones parciales. Las otras dos magnitudes se deducen por definición de masa y volumen.", "W se expresa en kg/kg de aire seco o g/kg de aire seco; γ en kg/kg de mezcla; densidad de vapor en kg/m³.", "Las líneas horizontales de la carta mantienen W constante. La humedad volumétrica no permanece necesariamente constante durante el calentamiento a W fija.", "", "W|pv|SpecificHumidity|VaporDensity", "10 g/kg de aire seco equivalen a W = 0,010 kg/kg y γ = 0,00990 kg/kg de mezcla.", Book),
        new AshraeStudyUnit("A6", "6", "Humedad relativa", "Indica la proximidad a la saturación del aire: se expresa como porcentaje de la presión parcial de vapor respecto a la presión de saturación a la misma temperatura, bajo la formulación de gases ideales.", "Al combinar la definición con la ecuación de razón de humedad se obtiene W con t, P y HR conocidas.", "φ es la humedad relativa porcentual; pᵥ es la presión parcial de vapor y p de saturación se evalúa a la temperatura seca.", "Al calentar aire sin añadir agua a presión fija, la humedad relativa desciende aunque W sea constante.", "", "RH|W", "A 25 °C con 50 % HR, pᵥ ≈ 1,585 kPa.", Book),
        new AshraeStudyUnit("A3", "7", "Entalpía del aire húmedo", "La entalpía es la propiedad energética h = u + Pv. Por kilogramo de aire seco, incluye la entalpía de este aire y la del vapor contenido en la mezcla.", "La suma de las contribuciones de aire seco y vapor, con referencia a 0 °C y calores específicos constantes, conduce a la expresión psicrométrica usual.", "t en °C, W en kg/kg de aire seco, h en kJ/kg de aire seco. 1,006 y 1,86 son calores específicos en kJ/(kg·K); 2501 es la entalpía de vaporización de referencia en kJ/kg.", "La diferencia de entalpías de dos corrientes permite calcular la potencia térmica cuando se conoce el caudal másico y se contabilizan los flujos de agua.", "", "h|Heat", "Para t = 25 °C y W = 0,010, h = 50,63 kJ/kg de aire seco.", Book),
        new AshraeStudyUnit("A8", "8", "Volumen específico y caudal másico", "El volumen específico v representa el volumen de la mezcla por unidad de masa de aire seco. Su inverso es la masa de aire seco por volumen de mezcla.", "Aplicando la ley de gas ideal a cada componente, se suma su contribución al volumen y se divide por la masa de aire seco.", "R del aire seco ≈ 0,287042 kPa·m³/(kg·K); P en kPa; T en K; v en m³/kg de aire seco. El caudal volumétrico se expresa en m³/s.", "Las isolíneas de volumen específico permiten convertir el caudal de un conducto en caudal másico necesario para los balances.", "", "v|Mdot", "Un caudal de 5 m³/s con v = 0,85 m³/kg corresponde a 5,882 kg/s de aire seco.", Book),
        new AshraeStudyUnit("A7", "9", "Temperatura de punto de rocío", "Temperatura a la cual comienza la condensación al enfriar el aire a presión constante sin modificar su contenido de vapor.", "Antes de condensar, W y la presión parcial de vapor permanecen constantes. El punto de rocío se encuentra igualando la presión de saturación a esa presión parcial.", "La temperatura de rocío se expresa en °C y se obtiene invirtiendo la relación de saturación.", "En la carta se avanza horizontalmente desde el estado hasta la curva de saturación. W y rocío son propiedades distintas, pero están relacionadas unívocamente a presión fija.", "", "Tdp|pv", "A 25 °C y 50 % HR, el rocío es aproximadamente 13,9 °C.", Book),
        new AshraeStudyUnit("A20", "10", "Temperatura de bulbo húmedo termodinámico", "Temperatura que alcanza el aire cuando se satura mediante evaporación adiabática de agua suministrada a la temperatura final.", "La energía y la masa del vapor añadido se equilibran mediante un balance estacionario del saturador. Las líneas de bulbo húmedo difieren ligeramente de las isoentálpicas debido a la entalpía del agua añadida.", "T* representa la temperatura de bulbo húmedo; h de saturación y W de saturación se evalúan a T*; h del agua se expresa en kJ/kg de agua.", "En aire no saturado el bulbo húmedo queda normalmente entre el punto de rocío y el bulbo seco; las tres coinciden a saturación.", "", "Tbh", "En aire a 25 °C y 50 % HR, el bulbo húmedo termodinámico está cerca de 18 °C.", Book),
        new AshraeStudyUnit("A9", "11", "Lectura de la carta psicrométrica", "Representación gráfica de las propiedades del aire húmedo a presión absoluta fija. Las coordenadas de esta carta son temperatura seca y razón de humedad.", "Cada familia de curvas corresponde a la ecuación de una propiedad mantenida constante. La intersección de dos propiedades independientes localiza un estado.", "La saturación corresponde a HR = 100 %. Las familias restantes incluyen HR, entalpía, bulbo húmedo y volumen específico.", "El punto de rocío se lee horizontalmente hasta saturación; la entalpía y el volumen se leen en sus respectivas líneas inclinadas.", "", "Ws|RH|h|v", "Una curva de 50 % HR se obtiene evaluando la razón de humedad para cada temperatura con φ = 50 %.", Book),
        new AshraeStudyUnit("A10", "12", "Construcción de la carta psicrométrica", "La carta se genera calculando pares de temperatura de bulbo seco y razón de humedad para cada valor constante de las propiedades.", "Primero se fija P, después se calcula la frontera de saturación y las curvas de humedad relativa; posteriormente se resuelven las ecuaciones de entalpía, bulbo húmedo y volumen específico.", "La ecuación correspondiente a una familia determina W para cada temperatura compatible con su valor.", "El trazado se limita al dominio con W no negativa y sin sobresaturación. El simulador permite visualizar progresivamente las familias.", "", "Ws|hInverse|vInverse|Tbh", "Para una entalpía de 50 kJ/kg y 25 °C, la razón de humedad resulta cercana a 9,76 g/kg.", Book),
        new AshraeStudyUnit("A11", "13", "Determinación del estado psicrométrico", "A presión conocida, se necesitan dos propiedades de estado independientes y compatibles para determinar las condiciones del aire húmedo.", "La solución puede obtenerse por despeje algebraico o por búsqueda numérica según el par elegido. W y punto de rocío a presión fija no son independientes.", "Las propiedades calculadas conservan la misma presión; el estado debe satisfacer el equilibrio de fases.", "Con bulbo seco y humedad relativa, se calcula la presión de vapor, W, h, v, rocío y bulbo húmedo.", "", "RH|W|h|v|Tdp|Tbh", "Introducir 25 °C, 50 % HR y 101,325 kPa determina un único estado gaseoso.", Book),
        new AshraeStudyUnit("A12", "14", "Calefacción y enfriamiento sensible", "Transformaciones en las que cambia la temperatura de bulbo seco sin que exista intercambio neto de agua. La calefacción reduce la HR y el enfriamiento la eleva.", "El balance de masa conserva W. El balance de energía estacionario, sin trabajo ni cambios apreciables de energía cinética o potencial, relaciona el calor con la diferencia de entalpías.", "Q̇ es potencia en kW; ṁ es caudal de aire seco en kg/s; h en kJ/kg de aire seco. Calor positivo hacia el aire.", "La trayectoria es horizontal; el enfriamiento sensible termina al alcanzar el punto de rocío.", "", "Heat|Sensible|Mdot", "Enfriar de 35 a 25 °C, con W = 0,010 y 5 m³/s de entrada. Calcular primero el caudal másico y después la potencia.", Book),
        new AshraeStudyUnit("A13", "15", "Humidificación por inyección de vapor", "Proceso en el que se suministra vapor de agua a una corriente de aire. Aumenta W y normalmente aumenta la entalpía.", "La masa de vapor inyectada es la diferencia entre el flujo de agua de salida y entrada. La energía que ingresa con el vapor es su flujo másico por su entalpía específica.", "La entalpía del vapor depende de su presión y temperatura; se expresa en kJ/kg de agua. El caudal de vapor se expresa en kg/s.", "La salida se halla a partir de W y h; su temperatura se obtiene invirtiendo la ecuación de entalpía.", "", "SteamW|SteamH|h", "Para 1 kg/s de aire seco, aumentar W de 8 a 10 g/kg exige 0,002 kg/s de vapor.", Book),
        new AshraeStudyUnit("A21", "16", "Humidificación evaporativa", "Se evapora agua líquida en el aire, aumentando la razón de humedad a costa de la energía sensible de la corriente. La temperatura desciende en un saturador adiabático.", "El balance de agua y energía determina el estado de saturación; la efectividad térmica compara el descenso real de temperatura con el máximo descenso al bulbo húmedo de entrada.", "ε es efectividad de saturación; las temperaturas en °C corresponden a entrada, salida y bulbo húmedo de entrada.", "La trayectoria se aproxima a una línea de bulbo húmedo constante; el valor de W de salida se obtiene del balance de energía.", "", "Evap|Tbh|SteamW", "Si el aire entra a 30 °C, su bulbo húmedo es 15 °C y ε = 0,70, sale a 19,5 °C.", Book),
        new AshraeStudyUnit("A14", "17", "Enfriamiento y deshumidificación por condensación", "Al enfriar por debajo del punto de rocío, una parte del vapor se transforma en agua líquida y se retira de la corriente. Disminuyen W, temperatura y entalpía.", "El balance de masa calcula el condensado y el balance de energía incluye la entalpía del líquido que sale. El enfriamiento sensible previo no cambia W.", "ṁ de condensado en kg/s; la entalpía del agua líquida se evalúa a su temperatura real; potencia de extracción positiva.", "La trayectoria puede representarse desde la entrada hacia el rocío y luego hacia la salida más fría, o mediante el modelo de serpentín.", "", "Condensate|Coil|Heat", "Aire inicial a 32 °C, con rocío de 28 °C, enfriado hasta 21 °C saturado: determinar el agua retirada y la potencia.", Book),
        new AshraeStudyUnit("A22", "18", "Deshumidificación mediante desecantes", "Un desecante retira vapor por adsorción o absorción. La energía de sorción puede elevar la temperatura del aire aunque se reduzca W.", "El balance de masa determina el agua retirada. El balance energético debe considerar intercambio térmico con el desecante y energía de sorción.", "La masa de agua se expresa en kg/s; las propiedades del material y su regeneración dependen del equipo.", "La disminución de W se lee en la carta; para hallar la temperatura final se requieren condiciones de operación del desecante.", "", "Condensate|Heat", "Con 1 kg/s de aire seco y una reducción de 4 g/kg se retiran 0,004 kg/s de vapor.", Book),
        new AshraeStudyUnit("A23", "19", "Calentamiento y humidificación combinados", "Proceso de acondicionamiento de aire frío y seco mediante un calentador y un humidificador. La secuencia de equipos debe satisfacer la temperatura y humedad de impulsión.", "Cada volumen de control conserva la masa de aire seco; la calefacción modifica h y la humidificación modifica W y h.", "Se distinguen los estados de entrada, salida del calentador y salida del humidificador; el caudal de vapor y el calor son magnitudes independientes.", "En la carta se enlazan los estados en el orden físico de los equipos y se calculan las cargas de cada tramo.", "", "Heat|SteamW|SteamH", "Para un aire frío que debe alcanzar 22 °C y 50 % HR, se calcula el estado intermedio según la tecnología del humidificador.", Book),
        new AshraeStudyUnit("A15", "20", "Mezcla adiabática de corrientes", "Combinación de dos o más corrientes de aire húmedo en una cámara sin intercambio de calor con el ambiente, sin condensación y sin trabajo.", "Se conservan el flujo másico de aire seco, el flujo de vapor y la energía. La salida se obtiene ponderando W y h por los caudales másicos de aire seco.", "Los caudales volumétricos de cada entrada deben convertirse con su propio volumen específico; la temperatura de mezcla se deduce de h y W.", "La mezcla queda entre las entradas en coordenadas h–W y más próxima a la de mayor caudal seco.", "", "Mdot|MixW|MixH|MixT", "Mezclar 3000 m³/h de retorno a 24 °C y 55 % HR con 500 m³/h de exterior a 32 °C y 70 % HR.", Book),
        new AshraeStudyUnit("A17", "21", "Factor de calor sensible del recinto y del sistema", "El factor de calor sensible (FCS o SHR) es la razón de potencia sensible a total. El factor del recinto (RSHF) utiliza las cargas internas del recinto; el factor global (GSHF) incorpora las cargas correspondientes a la frontera total, incluida la ventilación cuando corresponde.", "La carga total es suma algebraica de sensible y latente bajo una convención de signos consistente. La razón define la relación de cambios de temperatura y humedad, no la posición única del estado de impulsión.", "RSH y RLH son las potencias sensible y latente del recinto; GSH y GLH son las correspondientes al sistema global; todas en kW.", "La guía de FCS orienta el proceso desde un estado de referencia. Se necesita otra condición, por ejemplo caudal o temperatura de impulsión.", "", "SHR|RSHF|GSHF", "Con 150 kW sensibles y 50 kW latentes del recinto, RSHF = 0,75.", Book),
        new AshraeStudyUnit("A16", "22", "Punto de rocío de aparato y factor de bypass", "El punto de rocío de aparato (ADP) es la temperatura de saturación efectiva que resulta de prolongar la trayectoria idealizada de enfriamiento y deshumidificación hasta la curva de saturación. El factor de bypass (BF) expresa la fracción idealizada de aire que no alcanza ese estado.", "El modelo de mezcla de aire de entrada con aire saturado al ADP permite ponderar las entalpías y razones de humedad. El factor de contacto es 1 − BF.", "Los índices 1 y 2 identifican entrada y salida; ADP identifica el estado saturado efectivo; BF es adimensional, entre cero y uno.", "Con ADP, BF y entrada conocidos, se calcula la salida mediante W y h. BF depende del serpentín y del caudal.", "", "BF|BFW", "Para BF = 0,20, el estado de salida pondera 20 % de entrada y 80 % del estado ADP.", Book),
        new AshraeStudyUnit("A18", "23", "Climatización: ventilación, serpentín y ventilador", "La unidad de tratamiento de aire (UTA) acondiciona una mezcla de retorno y aire exterior mediante equipos de calentamiento, enfriamiento o humidificación. Los requerimientos dependen de las cargas del recinto y de las condiciones exteriores.", "Se aplica un balance de masa y energía a cada componente; un ventilador posterior al serpentín aumenta la temperatura de impulsión y un serpentín de agua fría transfiere calor al agua.", "El caudal de aire, carga térmica y caudal másico de agua se expresan en kg/s y kW; las temperaturas del agua en °C.", "En clima cálido húmedo se enfría y deshumidifica; en frío seco se calienta y humidifica. Las etapas se resuelven independientemente y se enlazan en la carta.", "", "MixW|MixH|Heat|Coil|WaterFlow", "Si el agua entra a 6 °C y sale a 12 °C en un equipo que extrae 120 kW, su caudal es 4,78 kg/s usando 4,18 kJ/(kg·K).", Book),
        new AshraeStudyUnit("A24", "24", "Desviación de entalpía y entropía", "La desviación de entalpía respecto al estado saturado a igual bulbo húmedo cuantifica la diferencia entre h del estado y la entalpía de saturación evaluada a Tbh. La entropía específica relativa caracteriza el estado respecto de una referencia definida.", "La desviación resulta del balance del saturador adiabático; la entropía de mezcla ideal suma contribuciones térmicas y de presiones parciales de cada componente.", "Δh se expresa en kJ/kg de aire seco y s* en kJ/(kg de aire seco·K). La entropía requiere una referencia coherente.", "Las isolíneas de estas propiedades son familias adicionales de la carta. La entropía permite estudiar irreversibilidades mediante balances de entropía.", "", "DeltaH|Entropy|EntropyT|EntropyPda|EntropyPv", "Si h = 50 y la entalpía saturada al mismo bulbo húmedo es 50,3 kJ/kg, Δh = −0,3 kJ/kg.", Book),
    };
