    {
        new AshraeEquation("W", "Razón de humedad", "W", "0,621945 · pᵥ", "P − pᵥ", "kg vapor/kg aire seco", "Aplicar las ecuaciones de gas ideal de ambos gases y dividir sus masas. La presión parcial del aire seco es la diferencia entre presión total y presión de vapor.", "W: masa de vapor por masa seca; P: presión absoluta en kPa; pᵥ: presión de vapor en kPa. 0,621945 es el cociente de masas molares.", ""),
        new AshraeEquation("pv", "Presión parcial de vapor", "pᵥ", "P · W", "0,621945 + W", "kPa absolutos", "Despejar la presión parcial de la ecuación de razón de humedad.", "P en kPa absolutos; W en kg de vapor por kg de aire seco.", ""),
        new AshraeEquation("RH", "Humedad relativa", "φ", "100 · pᵥ", "p_ws(Tbs)", "%", "Comparar presión de vapor con la de saturación a la temperatura seca y expresar el resultado porcentual.", "pᵥ y p_{ws} son las presiones de vapor y saturación en kPa; Tbs es temperatura seca.", ""),
        new AshraeEquation("Ws", "Razón de humedad a saturación", "Wₛ", "0,621945 · p_ws(T)", "P − p_ws(T)", "kg/kgda", "Sustituir la presión parcial por la presión de saturación en la ecuación de W.", "p_{ws}(T): presión de saturación a temperatura T; P: presión absoluta.", ""),
        new AshraeEquation("h", "Entalpía aproximada del aire húmedo", "h", "1,006·t + W·(2501 + 1,86·t)", "1", "kJ/kgda", "Sumar la entalpía del aire seco y la del vapor por cada kilogramo de aire seco.", "t en °C; W en kg/kg de aire seco; 1,006 y 1,86 son calores específicos y 2501 es la entalpía de vaporización a 0 °C.", ""),
        new AshraeEquation("v", "Volumen específico ideal", "v", "R_da·T_K·(1 + 1,607858·W)", "P", "m³/kgda (R y P coherentes)", "Aplicar la ley de gas ideal a ambos componentes y dividir el volumen total por la masa de aire seco.", "R_{da}: constante del aire seco (0,287042 kPa·m³/(kg·K)); T_{K}: temperatura absoluta; P en kPa.", ""),
        new AshraeEquation("Tdp", "Condición de punto de rocío", "p_ws(Tdp)", "P·W", "0,621945 + W", "kPa", "A presión y W constantes, la condensación empieza cuando la presión de saturación iguala la presión de vapor; invertir la correlación de saturación.", "Tdp es temperatura de rocío; p_{ws} es presión de saturación; P es presión absoluta.", ""),
        new AshraeEquation("Mdot", "Caudal másico de aire seco", "ṁ_da", "V̇", "v", "kgda/s", "El caudal másico seco se deduce dividiendo el caudal volumétrico entre el volumen específico.", "V̇ en m³/s; v en m³/kg de aire seco.", ""),
        new AshraeEquation("MixW", "Razón de humedad en mezcla", "W₃", "ṁ₁·W₁ + ṁ₂·W₂", "ṁ₁ + ṁ₂", "kg/kgda", "Igualar el flujo de vapor de entrada al flujo de vapor de salida.", "ṁ₁ y ṁ₂ en kg/s de aire seco; W₁ y W₂ en kg/kg de aire seco.", ""),
        new AshraeEquation("SHR", "Factor sensible del recinto", "FCS", "Q̇_sensible", "Q̇_total", "adimensional", "Dividir el calor sensible por el total evaluado en una misma frontera.", "Q̇_{sensible} y Q̇_{total}: potencias térmicas en kW.", ""),
        new AshraeEquation("BF", "Factor de bypass ideal", "BF", "h₂ − h_ADP", "h₁ − h_ADP", "adimensional", "Despejar el factor de bypass del balance de energía de la mezcla ideal.", "h₁ es entalpía de entrada; h₂ de salida; h_{ADP} corresponde al estado saturado al punto de rocío del aparato.", ""),
        new AshraeEquation("Tbh", "Balance de saturación adiabática", "hₛ(T*) − h₁", "[Wₛ(T*) − W₁]·h_w(T*)", "1", "kJ/kgda", "Igualar la diferencia de entalpías del aire con la entalpía del agua añadida durante la saturación adiabática.", "T* es bulbo húmedo termodinámico; hₛ y Wₛ son propiedades saturadas; h_{w} es entalpía del agua añadida.", ""),
        new AshraeEquation("Dalton", "Ley de Dalton", "P", "p_{da} + pᵥ", "1", "kPa", "La presión total es suma de presiones parciales.", "P: presión absoluta; p da: presión parcial de aire seco; pᵥ: presión parcial de vapor.", ""),
